     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	import { ZimmProductName } from 'app/components/ui-kits/atoms/zimmProductName';
     4	import { ZimmProductPrice } from 'app/components/ui-kits/atoms/zimmProductPrice';
     5	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
     6	
     7	const ZIMM_PRODUCT_CONTENT_RECIPE = 'ZimmProductContent';
     8	
     9	type ZimmProductContentProps = {
    10	  /** The product's display name. */
    11	  name: string;
    12	  /**
    13	   * Heading level for the name. Passed through rather than fixed here so the caller keeps
    14	   * control of the page's heading outline — see `ZimmProductName`.
    15	   */
    16	  headingLevel: 'h1' | 'h2' | 'h3';
    17	  /**
    18	   * Price, already formatted for the storefront's locale and currency by the caller. Optional
    19	   * for the same reason as `description`: `ZimmProductPrice` renders nothing when the value is
    20	   * absent or empty, so the group's `gap` collapses to whatever actually rendered.
    21	   */
    22	  price?: string;
    23	  /** Long description as authored in Business Manager. Omitted when the product has none. */
    24	  description?: string;
    25	};
    26	
    27	/**
    28	 * Molecule — the PDP text group: name, price, description.
    29	 *
    30	 * Model copy and the style code are deliberately *not* here. The design places them at the
    31	 * bottom of the column, after the accordions, so the page positions them itself rather than
    32	 * this molecule holding them and then having to unpick the order.
    33	 */
    34	export const ZimmProductContent = ({ name, headingLevel, price, description }: ZimmProductContentProps) => {
    35	  const styles = useStyleConfig(ZIMM_PRODUCT_CONTENT_RECIPE, {});
    36	
    37	  return (
    38	    <chakra.div __css={styles} data-testid="product-content">
    39	      <ZimmProductName name={name} as={headingLevel} />
    40	      <ZimmProductPrice price={price} />
    41	      <ZimmProductDescription description={description} />
    42	    </chakra.div>
    43	  );
    44	};

